// The seller block, held to every page the site serves.
//
// The company's own record is what a buyer checks the site against, and it is what a
// code-signing authority checks it against too: a website that names the entity it sells for is
// evidence a certificate can be issued on, and one that names nobody is not. So the block is
// declared once (`website/docs/contact.mjs`) and printed in the shared footer of every page —
// generated by `website/build-docs.mjs` or written by hand — and this holds both halves: the
// sentence still says what the register says, and no page has lost it.
import { readFileSync, readdirSync, statSync } from 'node:fs'
import { join } from 'node:path'
import { describe, expect, it } from 'vitest'
import { renderPage } from '../website/build-docs.mjs'
import { PAGES } from '../website/docs/pages.mjs'
import { SELLER, SELLER_BLOCK } from '../website/docs/contact.mjs'

/** The register's own values, as read on 2026-09-28. A change is an edit here and a re-read there. */
const REGISTER = {
  name: 'ALGD LTD',
  number: 'NI744090',
  address: '121 Glencam Road, Omagh, Tyrone, BT79 7HB, United Kingdom'
}

/** Every `.html` the deploy ships, from the site root down. */
function servedHtml(dir = 'website', found: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const path = join(dir, entry)
    if (statSync(path).isDirectory()) servedHtml(path, found)
    else if (entry.endsWith('.html')) found.push(path)
  }
  return found
}

describe('the seller block', () => {
  it('says what the register says, with no VAT claim and no second address', () => {
    expect(SELLER).toEqual(REGISTER)
    expect(SELLER_BLOCK).toContain(`company number ${REGISTER.number}`)
    expect(SELLER_BLOCK).toContain(REGISTER.address)
    // Not VAT registered, and a VAT line is a claim about tax status rather than a detail.
    expect(SELLER_BLOCK).not.toMatch(/\bVAT\b/i)
    expect(SELLER_BLOCK).not.toMatch(/@/)
  })

  it('is printed on every page this repository renders', () => {
    const missing = PAGES
      .filter(page => !renderPage(page).includes(SELLER_BLOCK))
      .map(page => page.path)
    expect(missing, `pages with no seller block: ${missing.join(', ')}`).toEqual([])
  })

  it('is printed on every page the site serves, hand-written ones included', () => {
    const files = servedHtml()
    expect(files.length, 'no pages found to check').toBeGreaterThan(10)
    const missing = files.filter(file => !readFileSync(file, 'utf8').includes(SELLER_BLOCK))
    expect(missing, `served pages with no seller block: ${missing.join(', ')}`).toEqual([])
  })
})
